552	### 3. JavaScript State Synchronization
553	
554	MANDATORY: Because `:user-invalid` is a visual state, you MUST provide a JavaScript bridge to sync `aria-invalid="true"` dynamically for assistive technologies when a user blurs an invalid field or attempts submission, deriving it from `:user-invalid`, not `checkValidity()`, which is already false when a user tabs through an untouched field.
555	
556	Native `:user-invalid` does not automatically sync with ARIA attributes. Add the following JavaScript to keep `aria-invalid` in sync with the visual state:
557	
558	* Set `aria-invalid="false"` until `:user-invalid` matches, rather than leaving it unset. Firefox and Safari expose an empty `required` field as invalid from page load, and Chromium doesn't expose an empty `required` field as invalid after interaction unless `aria-invalid="true"` is set.
559	* Link each field to its error message by setting the field's `data-error` attribute to the error message's `id` (`data-error="email-error"` for `<div id="email-error">`), and let the script list that `id` in `aria-describedby` only while the field is invalid. Don't reference the error from `aria-describedby` in the markup: the error element is always in the page, and text that `aria-describedby` references is announced even when it's hidden.
560	* Announce an error that appears when the user leaves or changes a field through one polite live region for the page, a moment later so it doesn't talk over the next field. Don't make each error message a live region: a live region that is shown, rather than changed, isn't announced reliably. After a failed submit, move focus to the first invalid field so that its error is announced instead.
561	
562	```javascript
563	// List the field's error message (the id in data-error) in aria-describedby only while
564	// it's shown: text that aria-describedby references is announced even when it's hidden.
565	const linkError = (el, shown) => {
566	  const errorId = el.dataset.error;
567	  if (!errorId) return;
568	  const ids = (el.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== errorId);
569	  if (shown) ids.push(errorId);
570	  if (ids.length) el.setAttribute('aria-describedby', ids.join(' '));
571	  else el.removeAttribute('aria-describedby');
572	};
573	
574	// One polite live region for the page announces an error that appears when the user
575	// leaves or changes a field. Run this once the form is in the page.
576	const announcer = document.createElement('div');
577	announcer.setAttribute('aria-live', 'polite');
578	announcer.classList.add('visually-hidden');
579	document.body.append(announcer);
580	let announceTimer;
581	let announcedField;
582	
583	// Text as a screen reader reads it: icons' text alternatives in, aria-hidden text out.
584	const spokenText = (node) => {
585	  const copy = node.cloneNode(true);
586	  copy.querySelectorAll('[aria-hidden="true"]').forEach((n) => n.remove());
587	  copy.querySelectorAll('[role="img"][aria-label]').forEach((n) => n.replaceWith(`${n.getAttribute('aria-label')}: `));
588	  return copy.textContent.replace(/\s+/g, ' ').trim();
589	};
590	const announceError = (el) => {
591	  const error = document.getElementById(el.dataset.error);
592	  if (!error) return;
593	  const label = el.labels?.[0] ? `${spokenText(el.labels[0])}: ` : '';
594	  clearTimeout(announceTimer);
595	  announcer.textContent = '';
596	  announcedField = el;
597	  // Wait until the screen reader has announced the field that receives focus next.
598	  announceTimer = setTimeout(() => { announcer.textContent = label + spokenText(error); }, 500);
599	};
600	
601	// Sync aria-invalid with the CSS :user-invalid state. Only form fields are synced, and
602	// an aria-invalid="true" that this script didn't set (for example from a server check)
603	// is left alone.
604	const flagged = new WeakSet();
605	// Fields whose current error has been announced, or read out by focus after a failed
606	// submit. A field can become invalid while the user types, so this is tracked separately.
607	const announced = new WeakSet();
608	const syncAria = (el, announce = false) => {
609	  if (!el.matches?.('input, select, textarea')) return;
610	  const invalid = el.matches(':user-invalid');
611	  if (invalid) {
612	    if (announce && !announced.has(el)) {
613	      announceError(el);
614	      announced.add(el);
615	    }
616	    el.setAttribute('aria-invalid', 'true');
617	    linkError(el, true);
618	    flagged.add(el);
619	  } else if (flagged.has(el) || el.getAttribute('aria-invalid') !== 'true') {
620	    el.setAttribute('aria-invalid', 'false');
621	    linkError(el, false);
622	    flagged.delete(el);
623	    announced.delete(el);
624	    // Clear a fixed field's announcement so it isn't found later when reading the page.
625	    if (announcedField === el) {
626	      clearTimeout(announceTimer);
627	      announcer.textContent = '';
628	    }
629	  }
630	};
631	
632	// Start every field at aria-invalid="false".
633	document.querySelectorAll('input, select, textarea').forEach((el) => syncAria(el));
634	
635	// Update on blur (to show and announce an error) and input (to clear it)
636	document.addEventListener('blur', (e) => syncAria(e.target, true), true);
637	document.addEventListener('input', (e) => {
638	  if (e.target.hasAttribute('aria-invalid')) syncAria(e.target);
639	});
640	
641	// Checkboxes, radio buttons and other controls that commit on 'change' can become
642	// :user-invalid without losing focus, so update on change too.
643	document.addEventListener('change', (e) => syncAria(e.target, true), true);
644	
645	// A failed submit fires 'invalid' on each failing field, including required fields the
646	// user never touched, so update those too. 'invalid' doesn't bubble. Focus moving to the
647	// first invalid field announces its error, so these aren't announced.
648	document.addEventListener('invalid', (e) => {
649	  announced.add(e.target);
650	  syncAria(e.target);
651	}, true);
652	
653	// Reset clears :user-invalid after the 'reset' event, so update each field afterwards.
654	document.addEventListener('reset', (e) => {
655	  setTimeout(() => [...e.target.elements].forEach((el) => syncAria(el)));
656	}, true);
