699	### JavaScript Fallback
700	
701	Use a reusable utility that tracks interaction state using a `WeakMap`. This avoids polluting the DOM with "dirty" classes or data attributes.
702	
703	```javascript
704	const UserInvalidFallback = (() => {
705	  const dirtyState = new WeakMap();
706	
707	  const updateState = (input) => {
708	    // validity.valid gives the current state without firing an 'invalid' event, as checkValidity() does.
709	    const isValid = input.validity.valid;
710	
711	    // Update both visual and ARIA state
712	    input.classList.toggle('user-invalid-fallback', !isValid);
713	    input.classList.toggle('user-valid-fallback', isValid);
714	
715	    input.setAttribute('aria-invalid', isValid ? 'false' : 'true');
716	    linkError(input, !isValid);
717	  };
718	
719	  // List the error message (the id in data-error) in aria-describedby only while it's
720	  // shown: text that aria-describedby references is announced even when it's hidden.
721	  const linkError = (input, shown) => {
722	    const errorId = input.dataset.error;
723	    if (!errorId) return;
724	    const ids = (input.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== errorId);
725	    if (shown) ids.push(errorId);
726	    if (ids.length) input.setAttribute('aria-describedby', ids.join(' '));
727	    else input.removeAttribute('aria-describedby');
728	  };
729	
730	  const handleEvent = (event) => {
731	    const input = event.target;
732	
733	    if (event.type === 'reset') {
734	      const controls = input.elements || [];
735	      for (const control of controls) {
736	        dirtyState.delete(control);
737	        control.classList.remove('user-invalid-fallback');
738	        control.classList.remove('user-valid-fallback');
739	        if (control.matches('input, select, textarea')) control.setAttribute('aria-invalid', 'false');
740	        if (control.dataset?.error) linkError(control, false);
741	      }
742	      return;
743	    }
744	
745	    if (!input.checkValidity) return;
746	
747	    // A submit attempt counts as interaction: the browser fires 'invalid' on each failing
748	    // field, including required fields the user never touched, so flag them all.
749	    if (event.type === 'invalid') {
750	      dirtyState.set(input, { hasInteracted: true, hasBlurred: true });
751	      updateState(input);
752	      return;
753	    }
754	
755	    if (event.type === 'input' || event.type === 'change') {
756	      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
757	      state.hasInteracted = true;
758	      dirtyState.set(input, state);
759	      if (state.hasBlurred) {
760	        updateState(input);
761	      }
762	    } else if (event.type === 'blur') {
763	      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
764	      state.hasBlurred = true;
765	      dirtyState.set(input, state);
766	      if (state.hasInteracted) {
767	        updateState(input);
768	      }
769	    }
770	  };
771	
772	  const init = (root = document) => {
773	    if (CSS.supports('selector(:user-invalid)')) return;
774	
775	    // Firefox and Safari expose an empty required field as invalid from page load.
776	    root.querySelectorAll('input, select, textarea').forEach((el) => {
777	      if (!el.hasAttribute('aria-invalid')) el.setAttribute('aria-invalid', 'false');
778	    });
779	
780	    root.addEventListener('blur', handleEvent, true); // Capture phase
781	    root.addEventListener('input', handleEvent);
782	    root.addEventListener('change', handleEvent);
783	    root.addEventListener('invalid', handleEvent, true); // invalid doesn't bubble
784	    root.addEventListener('reset', handleEvent, true); // Capture resets
785	  };
786	
787	  return { init };
788	})();
789	
790	// Initialize for a specific form
791	const form = document.querySelector('#demo-form');
792	UserInvalidFallback.init(form);
793	```
