/* Errors appear only after the user has edited and left a field (:user-invalid),
   or after a submit attempt (.was-submitted, set in app.js because the form uses novalidate).
   :is() is forgiving, so the rule still works where :user-invalid isn't supported. */
.error-msg { display: none; margin-top: 0.25rem; color: #b91c1c; font-size: 0.875rem; }
:is(input:user-invalid, .was-submitted input:invalid) { border: 2px solid #dc2626; background: #fef2f2; }
:is(input:user-invalid, .was-submitted input:invalid) + .error-msg { display: block; }
.visually-hidden:where(:not(:focus-within, :active)) {
  position: absolute !important; clip-path: inset(50%) !important; overflow: hidden !important;
  width: 1px !important; height: 1px !important; margin: -1px !important;
  padding: 0 !important; border: 0 !important; white-space: nowrap !important;
}

